#!/usr/bin/env python3
"""ARK document dogfood — renders the documents the product actually emits
(transactional email + the invoice) in a browser and verifies the law on the
computed DOM.

Why this exists: `ark.css` cannot travel with an email. Transactional mail and
the print-to-PDF invoice carry their own inline styles, so the pixel walk
(fixtures + marketing) never sees them. This tool closes that blind spot:

  * the artifacts are generated by the PRODUCT code
    (`render_transactional_email[_with_branding]`, `render_invoice_html`) via
    the committed test `ark_document_previews_are_written_and_carry_the_law`;
  * every document is rendered at 1440 and 390 CSS px, in light and in a
    dark-preferring browser;
  * the same ARK assertions are applied: square corners, no shadow, no
    gradient, ARK palette only, AA contrast per text node, the declared
    display/body/mono faces, no mobile overflow;
  * email documents must additionally stay paper/ink under `prefers-color-scheme:
    dark` (they declare `color-scheme: light only`).

Usage:
  python3 tools/ark_email_dogfood.py [--no-generate]
Writes: tools/contrast-audit/reports/ark-email/report.json + shots/*.png
"""

from __future__ import annotations

import argparse
import functools
import http.server
import json
import re
import socketserver
import subprocess
import sys
import threading
from pathlib import Path

from playwright.sync_api import sync_playwright

ROOT = Path(__file__).resolve().parent.parent
PREVIEW = ROOT / "services/mail-server/target/ark-email-preview"
REPORT = ROOT / "tools/contrast-audit/reports/ark-email"
SHOTS = REPORT / "shots"
PORT = 8013

BANNED_HUE_RE = re.compile(
    r"rgb\((99, 102, 241|139, 92, 246|168, 85, 247|126, 34, 206|79, 70, 229|"
    r"34, 197, 94|22, 163, 74|16, 185, 129|5, 150, 105|20, 83, 45|"
    r"236, 72, 153|244, 63, 94)\)"
)

PROBE_JS = r"""
() => {
  const out = {violations: [], samples: {}};
  const parse = (c) => {
    const m = c.match(/rgba?\(([^)]+)\)/);
    if (!m) return null;
    const p = m[1].split(',').map(Number);
    return {r:p[0], g:p[1], b:p[2], a:p.length > 3 ? p[3] : 1};
  };
  const lum = (c) => {
    const f = (v) => { v = v/255; return v <= 0.04045 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); };
    return 0.2126*f(c.r) + 0.7152*f(c.g) + 0.0722*f(c.b);
  };
  const ratio = (a,b) => { const la=lum(a), lb=lum(b); const hi=Math.max(la,lb), lo=Math.min(la,lb); return (hi+0.05)/(lo+0.05); };
  const bgOf = (el) => {
    let e = el;
    while (e) {
      const c = parse(getComputedStyle(e).backgroundColor);
      if (c && c.a > 0.5) return c;
      e = e.parentElement;
    }
    return {r:255,g:255,b:255,a:1};
  };
  const add = (kind, detail, el) => {
    if (out.violations.length > 40) return;
    out.violations.push({kind, detail, el: el ? el.tagName.toLowerCase() : ''});
  };
  const clipped = (cs, el) => (cs.clip && cs.clip !== 'auto' && cs.clip !== '') || (el.offsetWidth <= 1 && el.offsetHeight <= 1);
  const seen = new Set();
  for (const el of document.querySelectorAll('*')) {
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') continue;
    if (clipped(cs, el)) continue;
    if (cs.borderRadius !== '0px' && cs.borderRadius !== '') {
      const id = 'radius|' + cs.borderRadius; if (!seen.has(id)) { seen.add(id); add('radius', cs.borderRadius, el); }
    }
    if (cs.boxShadow && cs.boxShadow !== 'none') {
      const id = 'shadow|' + cs.boxShadow.slice(0, 40); if (!seen.has(id)) { seen.add(id); add('shadow', cs.boxShadow.slice(0, 60), el); }
    }
    const bi = cs.backgroundImage;
    if (bi && bi !== 'none' && !bi.includes('repeating-linear-gradient')) {
      const id = 'gradient|' + bi.slice(0, 50); if (!seen.has(id)) { seen.add(id); add('gradient', bi.slice(0, 80), el); }
    }
    const bg = cs.backgroundColor;
    if (bg && bg !== 'rgba(0, 0, 0, 0)' && /rgb\((99, 102, 241|139, 92, 246|168, 85, 247|126, 34, 206|79, 70, 229|34, 197, 94|22, 163, 74|16, 185, 129|5, 150, 105|20, 83, 45|236, 72, 153|244, 63, 94)\)/.test(bg)) {
      add('banned-hue', bg, el);
    }
    for (const node of el.childNodes) {
      if (node.nodeType !== 3 || node.textContent.trim().length < 2) continue;
      const fg = parse(cs.color);
      if (!fg) break;
      const own = parse(cs.backgroundColor);
      const bgc = own && own.a > 0.5 ? own : bgOf(el);
      const size = parseFloat(cs.fontSize);
      const weight = parseInt(cs.fontWeight) || 400;
      const large = size >= 24 || (size >= 18.66 && weight >= 700);
      const need = large ? 3.0 : 4.5;
      const r = ratio(fg, bgc);
      if (r < need - 0.01) {
        const id = 'contrast|' + r.toFixed(2) + '|' + node.textContent.trim().slice(0, 24);
        if (!seen.has(id)) { seen.add(id); add('contrast', `${r.toFixed(2)} < ${need} on rgb(${bgc.r},${bgc.g},${bgc.b}) ["${node.textContent.trim().slice(0, 40)}"]`, el); }
      }
      break;
    }
  }
  const body = getComputedStyle(document.body);
  out.samples.bodyFont = body.fontFamily;
  out.samples.bodyColor = body.color;
  out.samples.bodyBg = body.backgroundColor;
  out.samples.colorScheme = body.colorScheme || (document.documentElement.style.colorScheme || '');
  const h2 = document.querySelector('h2');
  if (h2) out.samples.headingFont = getComputedStyle(h2).fontFamily;
  const mono = document.querySelector('.apex-mono');
  if (mono) out.samples.monoFont = getComputedStyle(mono).fontFamily;
  const body3px = Array.from(document.querySelectorAll('*')).some((el) => {
    const cs = getComputedStyle(el);
    return cs.borderBottomWidth === '3px' || cs.borderTopWidth === '3px' ||
           cs.borderBottomWidth === '2px' || cs.borderTopWidth === '2px';
  });
  out.samples.rule = body3px;
  return out;
}
"""


class QuietHandler(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *args, **kwargs):
        return


class Quiet(socketserver.TCPServer):
    allow_reuse_address = True


def generate() -> None:
    print("[ark-email] generating product documents ...")
    proc = subprocess.run(
        ["cargo", "test", "-p", "api-server", "--lib", "ark_document_previews", "--", "--nocapture"],
        cwd=ROOT / "services/mail-server",
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        sys.stderr.write(proc.stdout[-4000:] + proc.stderr[-4000:])
        raise SystemExit("preview generation failed")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--no-generate", action="store_true")
    args = ap.parse_args()

    if not args.no_generate:
        generate()
    docs = sorted(PREVIEW.glob("*.html"))
    if not docs:
        raise SystemExit(f"no preview documents in {PREVIEW} — run without --no-generate")

    REPORT.mkdir(parents=True, exist_ok=True)
    SHOTS.mkdir(parents=True, exist_ok=True)
    handler = functools.partial(QuietHandler, directory=str(PREVIEW))
    httpd = Quiet(("127.0.0.1", PORT), handler)
    threading.Thread(target=httpd.serve_forever, daemon=True).start()

    failures: list[dict] = []
    shots = 0
    with sync_playwright() as pw:
        browser = pw.chromium.launch()
        for scheme in ("light", "dark"):
            ctx = browser.new_context(
                viewport={"width": 1440, "height": 900},
                color_scheme=scheme,
            )
            page = ctx.new_page()
            for doc in docs:
                slug = doc.stem
                is_email = slug.startswith("email-")
                url = f"http://127.0.0.1:{PORT}/{doc.name}"
                page.goto(url, wait_until="load", timeout=15000)
                page.wait_for_timeout(30)
                res = page.evaluate(PROBE_JS)
                page.screenshot(path=str(SHOTS / f"{slug}--{scheme}.png"), full_page=True)
                shots += 1
                for v in res["violations"]:
                    failures.append({"page": doc.name, "phase": scheme, **v})
                s = res["samples"]
                body_font = s.get("bodyFont") or ""
                if not body_font.startswith("Overpass"):
                    failures.append({"page": doc.name, "phase": scheme,
                                     "kind": "font", "detail": f"body font {body_font[:60]}"})
                if is_email:
                    heading = s.get("headingFont") or ""
                    if "Spectral" not in heading:
                        failures.append({"page": doc.name, "phase": scheme,
                                         "kind": "font", "detail": f"heading font {heading[:60]}"})
                if slug == "invoice":
                    mono = s.get("monoFont") or ""
                    if "Overpass Mono" not in mono:
                        failures.append({"page": doc.name, "phase": scheme,
                                         "kind": "font", "detail": f"mono font {mono[:60]}"})
                if s.get("bodyBg") != "rgb(255, 255, 255)":
                    failures.append({"page": doc.name, "phase": scheme,
                                     "kind": "paper", "detail": f"body bg {s.get('bodyBg')}"})
                if scheme == "dark" and is_email:
                    # Declared light-only: a dark-preferring client must still
                    # get paper and ink, not an inverted surface.
                    if s.get("bodyColor") != "rgb(14, 20, 27)":
                        failures.append({"page": doc.name, "phase": scheme,
                                         "kind": "scheme", "detail": f"body ink {s.get('bodyColor')}"})
                # 390 px: no horizontal overflow
                page.set_viewport_size({"width": 390, "height": 844})
                page.wait_for_timeout(30)
                overflow = page.evaluate(
                    "() => ({scroll: document.documentElement.scrollWidth, view: window.innerWidth})"
                )
                if overflow["scroll"] > overflow["view"] + 1:
                    failures.append({"page": doc.name, "phase": f"{scheme}-mobile",
                                     "kind": "overflow",
                                     "detail": f"scrollWidth {overflow['scroll']} > {overflow['view']}"})
                page.screenshot(path=str(SHOTS / f"{slug}--{scheme}-390.png"), full_page=True)
                shots += 1
                page.set_viewport_size({"width": 1440, "height": 900})
            ctx.close()
        browser.close()

    report = {
        "documents": [d.name for d in docs],
        "screenshots": shots,
        "failures": failures,
        "violations_total": len(failures),
    }
    (REPORT / "report.json").write_text(json.dumps(report, indent=2))
    print(f"documents: {len(docs)}, screenshots: {shots}, violations: {len(failures)}")
    for f in failures[:40]:
        print(" ", f["page"], f["phase"], f["kind"], ":", str(f["detail"])[:120])
    return 0 if not failures else 1


if __name__ == "__main__":
    sys.exit(main())
